<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Animated Solar System</title>
<style>
  html,body {margin:0;height:100%;background:#000;overflow:hidden;}
  canvas {display:block;width:100%;height:100%;}
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const resize = () => {
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
  };
  window.addEventListener('resize', resize);
  resize();

  const cx = canvas.width / (2 * dpr);
  const cy = canvas.height / (2 * dpr);
  const starCount = 300;
  const stars = [];
  for (let i = 0; i < starCount; i++) {
    stars.push({
      x: Math.random() * canvas.width / dpr,
      y: Math.random() * canvas.height / dpr,
      r: Math.random() * 1.2 + 0.2
    });
  }

  const planets = [
    {name:'Mercury', orbit:60,  size:3,  color:'#a7a7a7', speed:0.047},
    {name:'Venus',   orbit:90,  size:5,  color:'#c89b3c', speed:0.035},
    {name:'Earth',   orbit:120, size:5,  color:'#2e82ff', speed:0.029},
    {name:'Mars',    orbit:150, size:4,  color:'#b84a31', speed:0.024},
    {name:'Jupiter', orbit:200, size:9,  color:'#d9b38a', speed:0.013},
    {name:'Saturn',  orbit:260, size:8,  color:'#c2b280', speed:0.010},
    {name:'Uranus',  orbit:320, size:7,  color:'#7fdbff', speed:0.007},
    {name:'Neptune', orbit:380, size:7,  color:'#5a5aff', speed:0.005}
  ];

  const start = Date.now();

  function draw() {
    const now = (Date.now() - start) / 1000; // seconds
    ctx.clearRect(0,0,canvas.width/dpr,canvas.height/dpr);

    // starfield
    ctx.fillStyle = '#fff';
    stars.forEach(s=>{ ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,2*Math.PI); ctx.fill(); });

    // Sun
    const sunRadius = 15;
    ctx.fillStyle = '#ffcc33';
    ctx.beginPath();
    ctx.arc(cx, cy, sunRadius, 0, 2*Math.PI);
    ctx.fill();

    // Planets
    planets.forEach(p => {
      const angle = now * p.speed * 2*Math.PI;
      const x = cx + Math.cos(angle) * p.orbit;
      const y = cy + Math.sin(angle) * p.orbit;

      // orbit path
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      ctx.beginPath();
      ctx.arc(cx, cy, p.orbit, 0, 2*Math.PI);
      ctx.stroke();

      // planet
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(x, y, p.size, 0, 2*Math.PI);
      ctx.fill();

      // label
      ctx.fillStyle = '#fff';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(p.name, x, y - p.size - 4);
    });

    requestAnimationFrame(draw);
  }
  draw();
})();
</script>
</body>
</html>
```

The script draws a static starfield, then repeatedly computes each planet’s angular position from elapsed time to render the Sun, orbit paths, planets, and their labels on the canvas.
